package com.allinone.supply.domain;
import com.allinone.common.annotation.Excel;
public class LedgerRow { private Long orderId; @Excel(name="订单号") private String orderNumber; @Excel(name="供应商") private String supplierName; @Excel(name="订单金额（元）") private Long totalCents; @Excel(name="已入库数量") private Long receivedQuantity; @Excel(name="已通过发票金额（元）") private Long approvedInvoiceCents; @Excel(name="待审发票金额（元）") private Long pendingInvoiceCents; @Excel(name="订单状态") private String approvalStatus;
 public Long getOrderId(){return orderId;} public void setOrderId(Long v){orderId=v;} public String getOrderNumber(){return orderNumber;} public void setOrderNumber(String v){orderNumber=v;} public String getSupplierName(){return supplierName;} public void setSupplierName(String v){supplierName=v;} public Long getTotalCents(){return totalCents;} public void setTotalCents(Long v){totalCents=v;} public Long getReceivedQuantity(){return receivedQuantity;} public void setReceivedQuantity(Long v){receivedQuantity=v;} public Long getApprovedInvoiceCents(){return approvedInvoiceCents;} public void setApprovedInvoiceCents(Long v){approvedInvoiceCents=v;} public Long getPendingInvoiceCents(){return pendingInvoiceCents;} public void setPendingInvoiceCents(Long v){pendingInvoiceCents=v;} public String getApprovalStatus(){return approvalStatus;} public void setApprovalStatus(String v){approvalStatus=v;}
}
